mapper.select:
select
a.plan_id,
a.plan_name,
a.type,
a.plan_point_types,
a.create_time,
a.update_time
from t_cruise_plan a
where 1 = 1
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.plan_name = #{planName, jdbcType=VARCHAR}
 and a.type = #{type, jdbcType=INTEGER}
 and a.plan_point_types = #{planPointTypes, jdbcType=VARCHAR}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
